// ============================================================
// CONFIG_GLOBAL — ÚNICO DATO QUE DEBES PEGAR MANUALMENTE:
// 1) Sube "Cafeteria_N8N_Google_Sheets.xlsx" a Google Drive.
// 2) Ábrelo como Google Sheets.
// 3) Copia el ID de la URL:
//    https://docs.google.com/spreadsheets/d/ESTE_ES_EL_ID/edit
// 4) Reemplaza SOLO el texto PEGA_AQUI_EL_ID_DE_GOOGLE_SHEETS.
// ============================================================

const SPREADSHEET_ID = 'PEGA_AQUI_EL_ID_DE_GOOGLE_SHEETS';

const u = $json;
const msg = u.message || u.edited_message || null;
const cb = u.callback_query || null;
const chat = msg?.chat || cb?.message?.chat || {};
const from = msg?.from || cb?.from || {};
const rawText = String(msg?.text || '').trim();
const callbackData = String(cb?.data || '').trim();

function normalizar(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const key = normalizar(callbackData || rawText);
let action = 'DESCONOCIDO';
let pedidoId = '';
let detalle = '';

if (['/start', 'start', 'inicio', 'hola', 'buenas', 'menu principal', '🏠 inicio'].includes(key)) {
  action = 'INICIO';
} else if (['consultar_menu', 'consultar menu', 'menu', '/menu', '📋 consultar menu'].includes(key)) {
  action = 'CONSULTAR_MENU';
} else if (['realizar_pedido', 'realizar pedido', 'pedido', '/pedido', '🛒 realizar pedido'].includes(key)) {
  action = 'REALIZAR_PEDIDO';
} else if (key.startsWith('confirm:')) {
  action = 'CONFIRMAR_PEDIDO';
  pedidoId = callbackData.split(':').slice(1).join(':').trim();
} else if (key.startsWith('cancel:')) {
  action = 'CANCELAR_PEDIDO';
  pedidoId = callbackData.split(':').slice(1).join(':').trim();
} else if (/^pedido\s*:/i.test(rawText)) {
  action = 'REGISTRAR_PEDIDO';
  detalle = rawText.replace(/^pedido\s*:/i, '').trim();
} else if (['ayuda', '/ayuda', 'help'].includes(key)) {
  action = 'DESCONOCIDO';
}

return [{
  json: {
    spreadsheetId: SPREADSHEET_ID,
    chatId: chat.id ?? '',
    telegramUserId: from.id ?? '',
    username: from.username ?? '',
    nombre: [from.first_name, from.last_name].filter(Boolean).join(' '),
    rawText,
    callbackData,
    callbackQueryId: cb?.id || '',
    isCallback: !!cb,
    action,
    pedidoId,
    detalle
  }
}];

const base = $('CONFIG_GLOBAL').first().json;
const cfg = {};

for (const item of $input.all()) {
  const k = String(item.json.CLAVE || '').trim();
  if (!k) continue;
  cfg[k] = item.json.VALOR;
}

return [{
  json: {
    ...base,
    nombreCafeteria: String(cfg.NOMBRE_CAFETERIA || 'Cafetería Campus'),
    timezone: String(cfg.TIMEZONE || 'America/Bogota'),
    diasAtencion: String(cfg.DIAS_ATENCION || '1,2,3,4,5'),
    horaInicio: String(cfg.HORA_APERTURA || '08:00'),
    horaFin: String(cfg.HORA_CIERRE || '17:00'),
    moneda: String(cfg.MONEDA || 'COP'),
    mensajeCerrado: String(
      cfg.MENSAJE_CERRADO ||
      '🌙 Cafetería Cerrada. Nuestro horario es de Lunes a Viernes, 8am a 5pm. ¡Te esperamos mañana!'
    ),
    instruccionPedido: String(
      cfg.INSTRUCCION_PEDIDO ||
      'Escribe tu pedido así: PEDIDO: 1 Café Americano, 2 Empanadas'
    )
  }
}];

const base = $('Aplicar CONFIG').first().json;
const rows = $input.all()
  .map(i => i.json)
  .filter(r => String(r.DISPONIBLE || '').trim().toUpperCase() !== 'NO')
  .sort((a, b) => Number(a.ORDEN || 999) - Number(b.ORDEN || 999));

const groups = {};
for (const r of rows) {
  const cat = String(r.CATEGORIA || 'Otros');
  if (!groups[cat]) groups[cat] = [];
  groups[cat].push(r);
}

let text = `📋 <b>MENÚ — ${base.nombreCafeteria}</b>\n`;
for (const [cat, items] of Object.entries(groups)) {
  text += `\n<b>${cat}</b>\n`;
  for (const r of items) {
    const price = Number(r.PRECIO || 0).toLocaleString('es-CO');
    text += `• <b>${r.PRODUCTO}</b> — $${price} ${base.moneda}\n`;
    if (r.DESCRIPCION) text += `  <i>${r.DESCRIPCION}</i>\n`;
  }
}
text += `\n🕒 Horario para pedidos: Lunes a Viernes, ${base.horaInicio}–${base.horaFin}.`;
text += `\n✅ El menú puede consultarse incluso cuando la cafetería está cerrada.`;

return [{ json: { ...base, menuTexto: text } }];

const j = $json;
const now = new Date();
const local = new Intl.DateTimeFormat('sv-SE', {
  timeZone: j.timezone,
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
  hour12: false
}).format(now);

const pedidoId = `PED-${Date.now()}-${String(j.chatId).slice(-5)}`;

return [{
  json: {
    ...j,
    PEDIDO_ID: pedidoId,
    FECHA_CREACION: now.toISOString(),
    FECHA_CONFIRMACION: '',
    CHAT_ID: String(j.chatId),
    TELEGRAM_USER_ID: String(j.telegramUserId),
    USERNAME: j.username || '',
    NOMBRE: j.nombre || '',
    DETALLE: j.detalle || '',
    ESTADO: 'PENDIENTE',
    CANAL: 'Telegram',
    HORA_LOCAL: local
  }
}];

const j = $json;
const now = new Date();
const local = new Intl.DateTimeFormat('sv-SE', {
  timeZone: j.timezone,
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
  hour12: false
}).format(now);

return [{
  json: {
    ...j,
    PEDIDO_ID: j.pedidoId,
    FECHA_CONFIRMACION: now.toISOString(),
    ESTADO: 'CONFIRMADO',
    HORA_LOCAL: local
  }
}];

